function shortestTimes(n, edges, src) {
  const adj = Array.from({ length: n }, () => []), dist = Array(n).fill(Infinity) //@init
  for (const [a, b, w] of edges) adj[a].push([b, w]) //@build
  dist[src] = 0; const pq = [[0, src]] //@start
  while (pq.length) {
    const [d, v] = pq.shift() //@pop
    if (d > dist[v]) continue //@stale
    for (const [u, w] of adj[v]) {
      if (d + w >= dist[u]) continue //@relax
      dist[u] = d + w; pq.push([dist[u], u]); pq.sort((x, y) => x[0] - y[0] || x[1] - y[1]) //@push
    }
  }
  return dist.map(x => x === Infinity ? -1 : x) //@done
}

