function dijkstra(adj, src) { // adj[v] = [[u, w], ...] with w >= 0
  const dist = Array(adj.length).fill(Infinity)
  dist[src] = 0
  const heap = new Heap((x, y) => x[0] - y[0])
  heap.push([0, src])
  while (heap.size) {
    const [d, v] = heap.pop()
    if (d > dist[v]) continue // stale entry: v was settled cheaper
    for (const [u, w] of adj[v]) {
      if (d + w < dist[u]) {
        dist[u] = d + w
        heap.push([dist[u], u])
      }
    }
  }
  return dist
}

