import heapq

def cheapest_trip(n, roads, src, dst):
    adj = [[] for _ in range(n)]
    for a, b, cost in roads:
        adj[a].append((b, cost))
        adj[b].append((a, cost))
    dist = [float('inf')] * n
    dist[src] = 0
    heap = [(0, src)]
    while heap:
        d, v = heapq.heappop(heap)
        if d > dist[v]:
            continue
        if v == dst:
            return d
        for u, cost in adj[v]:
            if dist[u] == float('inf'):
                dist[u] = d + cost
                heapq.heappush(heap, (dist[u], u))
    return -1

